import random
from math import inf

import igraph as ig
import pytest

from lab5.ford_fulkerson import FordFulkerson, ResidualNetwork, bfs, get_path, init
from lab5.random_flow_network import RandomFlowNetwork

SEEDS = range(30)
NS = [2, 3, 4]

# Test Generated by AI at my request


@pytest.fixture(params=[(n, seed) for n in NS for seed in SEEDS])
def rfn(request) -> RandomFlowNetwork:
    """Losowa siec z zadania 1 (po wywolaniu run)"""
    n, seed = request.param
    random.seed(seed)
    rfn = RandomFlowNetwork(n)
    rfn.run()
    return rfn


def small_Gf(edges, capacities, flows) -> ResidualNetwork:
    G = ig.Graph(directed=True, edges=edges)
    G.es["weight"] = capacities
    Gf = ResidualNetwork(G)
    Gf.f = list(flows)
    return Gf


# ResidualNetwork


def test_residual_network_init(rfn):
    G = rfn.graph
    Gf = ResidualNetwork(G)
    assert Gf.f == [0] * G.ecount()
    assert Gf.c == G.es["weight"]
    assert list(zip(Gf.us, Gf.vs)) == G.get_edgelist()


def test_cf_forward_and_backward():
    Gf = small_Gf([(0, 1)], [7], [3])
    assert Gf.cf(0, forward=True) == 4
    assert Gf.cf(0, forward=False) == 3


def test_neighbors_zero_flow_only_forward():
    Gf = small_Gf([(0, 1), (2, 0)], [5, 5], [0, 0])
    assert Gf.neighbors(0) == [(1, 0, True)]


def test_neighbors_full_edge_gives_only_backward():
    Gf = small_Gf([(0, 1)], [5], [5])
    assert Gf.neighbors(0) == []
    assert Gf.neighbors(1) == [(0, 0, False)]


def test_neighbors_partial_edge_both_ways():
    Gf = small_Gf([(0, 1)], [5], [2])
    assert Gf.neighbors(0) == [(1, 0, True)]
    assert Gf.neighbors(1) == [(0, 0, False)]


def test_save_flow():
    Gf = small_Gf([(0, 1), (1, 2)], [5, 5], [3, 2])
    Gf.save_flow()
    assert Gf.G.es["flow"] == [3, 2]


# init / bfs / get_path


def test_init(rfn):
    ds, ps = init(ResidualNetwork(rfn.graph), rfn.s)
    assert ds[rfn.s] == 0
    assert all(d == inf for v, d in enumerate(ds) if v != rfn.s)
    assert ps == [None] * rfn.graph.vcount()


def test_bfs_path_is_shortest_walk_from_s_to_t(rfn):
    G = rfn.graph
    p = bfs(ResidualNetwork(G), rfn.s, rfn.t)
    assert p is not None
    assert len(p) == G.distances(rfn.s, rfn.t, mode="out")[0][0]

    v = rfn.s
    for edge_id, forward in p:
        edge = G.es[edge_id]
        assert forward
        assert edge.source == v
        v = edge.target
    assert v == rfn.t


def test_bfs_none_when_s_edges_full():
    Gf = small_Gf([(0, 1), (1, 2)], [3, 5], [3, 3])
    assert bfs(Gf, 0, 2) is None


def test_bfs_uses_backward_edge():
    # 2->1 ma przeplyw, wiec z 1 do 2 da sie dojsc tylko pod prad
    Gf = small_Gf([(0, 1), (2, 1), (2, 3)], [1, 1, 1], [0, 1, 0])
    assert bfs(Gf, 0, 3) == [(0, True), (1, False), (2, True)]


def test_get_path():
    # s=0 -> 1 -> 2=t, druga krawedz pod prad
    ps = [None, (0, 4, True), (1, 7, False)]
    assert get_path(ps, 0, 2) == [(4, True), (7, False)]


# FordFulkerson.run


def test_run_returns_graph(rfn):
    assert FordFulkerson(rfn.graph, rfn.s, rfn.t).run() is rfn.graph


def test_max_flow_equals_igraph(rfn):
    expected = rfn.graph.maxflow_value(rfn.s, rfn.t, capacity="weight")
    ff = FordFulkerson(rfn.graph, rfn.s, rfn.t)
    ff.run()
    assert ff.max_flow == expected


def test_flow_within_capacity(rfn):
    G = FordFulkerson(rfn.graph, rfn.s, rfn.t).run()
    for edge in G.es:
        assert 0 <= edge["flow"] <= edge["weight"]


def test_flow_conservation(rfn):
    G = FordFulkerson(rfn.graph, rfn.s, rfn.t).run()
    for v in range(G.vcount()):
        if v in (rfn.s, rfn.t):
            continue
        flow_in = sum(G.es[e]["flow"] for e in G.incident(v, mode="in"))
        flow_out = sum(G.es[e]["flow"] for e in G.incident(v, mode="out"))
        assert flow_in == flow_out


def test_out_of_s_equals_into_t(rfn):
    ff = FordFulkerson(rfn.graph, rfn.s, rfn.t)
    G = ff.run()
    out_of_s = sum(G.es[e]["flow"] for e in G.incident(rfn.s, mode="out"))
    into_t = sum(G.es[e]["flow"] for e in G.incident(rfn.t, mode="in"))
    assert out_of_s == into_t == ff.max_flow


def test_no_augmenting_path_after_run(rfn):
    G = FordFulkerson(rfn.graph, rfn.s, rfn.t).run()
    Gf = ResidualNetwork(G)
    Gf.f = G.es["flow"]
    assert bfs(Gf, rfn.s, rfn.t) is None


def test_backward_edge_cancels_flow():
    # s=0 a=1 b=2 c=3 e=4 d=5 f=6 t=7, wszystkie przepustowosci 1
    # najkrotsza s-a-b-t blokuje reszte, druga sciezka musi cofnac przeplyw na a->b:
    # s-c-e-b, wstecz b->a, a-d-f-t
    edges = [(0, 1), (1, 2), (2, 7), (0, 3), (3, 4), (4, 2), (1, 5), (5, 6), (6, 7)]
    G = ig.Graph(directed=True, edges=edges)
    G.es["weight"] = [1] * len(edges)
    ff = FordFulkerson(G, 0, 7)
    ff.run()

    assert ff.max_flow == 2
    assert G.es[G.get_eid(1, 2)]["flow"] == 0


def test_run_twice_gives_same_result(rfn):
    ff = FordFulkerson(rfn.graph, rfn.s, rfn.t)
    ff.run()
    first = ff.max_flow
    ff.run()
    assert ff.max_flow == first
